package com.vncnt.music.core.db

import androidx.room.ConstructedBy
import androidx.room.Database
import androidx.room.RoomDatabase
import androidx.room.RoomDatabaseConstructor
import androidx.room.migration.Migration
import androidx.sqlite.SQLiteConnection

// Canonical database definition. Same entities, version, and migration as the
// Android original — existing installs upgrade with no wipe. The Context-bound
// singleton factory lives in androidMain; the per-target constructor actuals
// are generated by Room's KSP processor (never handwritten).
@Database(
    entities = [TrackEntity::class, LyricsEntity::class],
    version = 5,
    exportSchema = false
)
@ConstructedBy(AppDatabaseConstructor::class)
abstract class AppDatabase : RoomDatabase() {
    abstract fun musicDao(): MusicDao
    abstract fun lyricsDao(): LyricsDao

    companion object {
        const val FILE_NAME = "aura_music_db"

        /**
         * v4 -> v5: no schema change (identity hardening release). Explicit
         * migration so upgrades never wipe the user's offline library.
         */
        val MIGRATION_4_5 = object : Migration(4, 5) {
            // NOTE: shared-code spelling is migrate(connection: SQLiteConnection);
            // the SupportSQLiteDatabase overload exists only on Android/JVM-framework.
            override fun migrate(connection: SQLiteConnection) {
                // No-op: schema identical, version bump only.
            }
        }
    }
}

/**
 * Constructor hook. Deliberately expect-only: Room generates the actual
 * implementations per target at KSP time. Do NOT add handwritten actuals —
 * @ConstructedBy must resolve to this expect declaration.
 */
@Suppress("NO_ACTUAL_FOR_EXPECT")
expect object AppDatabaseConstructor : RoomDatabaseConstructor<AppDatabase>
